private boolean cors(HttpExchange exchange) throws IOException {
    String origin = exchange.getRequestHeaders().getFirst("Origin");
    if (origin == null || origin.isBlank()) return false;
    String allowed = environment.get("JI_RELAY_ALLOWED_ORIGIN");
    if (allowed == null || !constant(allowed, origin)) {
        if ("OPTIONS".equals(exchange.getRequestMethod())) status(exchange, 403);
        return "OPTIONS".equals(exchange.getRequestMethod());
    }
    exchange.getResponseHeaders().set("Access-Control-Allow-Origin", allowed);
    exchange.getResponseHeaders().set("Vary", "Origin");
    if (!"OPTIONS".equals(exchange.getRequestMethod())) return false;
    exchange.getResponseHeaders().set("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS");
    exchange.getResponseHeaders().set("Access-Control-Allow-Headers", "Authorization, Content-Type");
    exchange.sendResponseHeaders(204, -1);
    exchange.close();
    return true;
}

